const assert = require('node:assert/strict');
const { ProfileService } = require('../.build/service');
const make = () => new ProfileService({ displayName: 'before', tags: ['old'] });
const snapshot = (s) => JSON.parse(JSON.stringify(s.profile));

// Valid cases
{
  const s = make();
  assert.deepEqual(s.patch({}), { displayName: 'before', tags: ['old'] });
  assert.deepEqual(s.patch({ displayName: '  hi  ' }), { displayName: 'hi', tags: ['old'] });
  assert.deepEqual(s.patch({ displayName: null }), { displayName: null, tags: ['old'] });
  assert.deepEqual(s.patch({ tags: null }), { displayName: null, tags: [] });
  assert.deepEqual(s.patch({ tags: [' a ', 'b'] }), { displayName: null, tags: ['a', 'b'] });
  assert.deepEqual(s.patch({ tags: [] }), { displayName: null, tags: [] });
  assert.deepEqual(s.patch({ displayName: 'x'.repeat(40), tags: ['1', '2', '3', '4', 'a'.repeat(12)] }).tags.length, 5);
  const nullProto = Object.create(null); nullProto.displayName = 'np';
  assert.equal(s.patch(nullProto).displayName, 'np');
}

// Input not mutated, tags array not reused
{
  const s = make();
  const tags = [' a ', 'b'];
  const input = { tags };
  s.patch(input);
  assert.deepEqual(input, { tags: [' a ', 'b'] });
  assert.notEqual(s.profile.tags, tags);
  tags.push('c');
  assert.deepEqual(s.profile.tags, ['a', 'b']);
}

// Invalid cases leave storage unchanged
const invalid = [
  null, undefined, 1, 'x', [], [1], new Date(), Object.create({}),
  { other: 1 }, { displayName: 'ok', extra: true }, { [Symbol('s')]: 1 },
  { displayName: '' }, { displayName: '   ' }, { displayName: 'x'.repeat(41) }, { displayName: 5 },
  { displayName: undefined }, { tags: undefined }, { tags: 'a' }, { tags: {} }, { tags: [1] },
  { tags: [''] }, { tags: ['  '] }, { tags: ['a', ' a'] }, { tags: ['1', '2', '3', '4', '5', '6'] },
  { tags: ['a'.repeat(13)] }, { tags: [null] }, { tags: [, 'a'] }, // eslint-disable-line no-sparse-arrays
  { displayName: 'good', tags: [3] },
  Object.defineProperty({}, 'displayName', { get() { return 'x'; }, enumerable: true }),
];
for (const input of invalid) {
  const s = make();
  const before = snapshot(s);
  assert.throws(() => s.patch(input), /^Error: invalid profile$/, `expected rejection: ${String(input && JSON.stringify(input))}`);
  assert.deepEqual(snapshot(s), before);
}
console.log('patch checks passed');

